import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { Link } from 'react-router-dom';

const PageContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const PageHeader = styled.div`
  margin-bottom: 40px;
  text-align: center;
`;

const PageTitle = styled.h1`
  color: #333;
  margin-bottom: 15px;
  position: relative;
  display: inline-block;
  
  &:after {
    content: '';
    display: block;
    width: 80px;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin: 15px auto 0;
    border-radius: 3px;
  }
`;

const PageDescription = styled.p`
  color: #666;
  font-size: 1.2rem;
  max-width: 800px;
  margin: 0 auto 30px;
  line-height: 1.6;
`;

const ShoppingListContainer = styled.div`
  display: grid;
  grid-template-columns: 1fr 350px;
  gap: 30px;
  
  @media (max-width: 992px) {
    grid-template-columns: 1fr;
  }
`;

const ShoppingListPanel = styled.div`
  background-color: white;
  border-radius: 12px;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  padding: 30px;
`;

const SidePanel = styled.div`
  @media (max-width: 992px) {
    order: -1;
  }
`;

const PanelTitle = styled.h2`
  color: #333;
  margin-bottom: 25px;
  font-size: 1.6rem;
  position: relative;
  
  &:after {
    content: '';
    display: block;
    width: 50px;
    height: 2px;
    background: #4CAF50;
    margin-top: 8px;
  }
`;

const InputGroup = styled.div`
  margin-bottom: 20px;
  display: flex;
  gap: 10px;
`;

const Input = styled.input`
  flex: 1;
  padding: 12px 15px;
  border: 1px solid #ddd;
  border-radius: 6px;
  font-size: 1rem;
  
  &:focus {
    outline: none;
    border-color: #4CAF50;
  }
`;

const QuantityInput = styled(Input)`
  width: 100px;
  flex: 0 0 auto;
`;

const Select = styled.select`
  padding: 12px 15px;
  border: 1px solid #ddd;
  border-radius: 6px;
  font-size: 1rem;
  min-width: 120px;
  
  &:focus {
    outline: none;
    border-color: #4CAF50;
  }
`;

const Button = styled.button`
  padding: 12px 20px;
  background-color: #4CAF50;
  color: white;
  border: none;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #45a049;
    transform: translateY(-2px);
  }
  
  &:disabled {
    background-color: #ccc;
    cursor: not-allowed;
    transform: none;
  }
`;

const ClearButton = styled(Button)`
  background-color: #f44336;
  
  &:hover {
    background-color: #d32f2f;
  }
`;

const SaveButton = styled(Button)`
  background-color: #2196F3;
  
  &:hover {
    background-color: #1976D2;
  }
`;

const PrintButton = styled(Button)`
  background-color: #FF9800;
  
  &:hover {
    background-color: #F57C00;
  }
`;

const ButtonsContainer = styled.div`
  display: flex;
  gap: 10px;
  margin-top: 20px;
  
  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const ListContainer = styled.div`
  margin-top: 30px;
`;

const CategoryList = styled.div`
  margin-bottom: 30px;
`;

const CategoryHeader = styled.div`
  padding: 15px;
  background-color: #f8f8f8;
  border-radius: 8px;
  margin-bottom: 15px;
  font-weight: 600;
  color: #333;
`;

const ItemList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const ItemRow = styled.li`
  padding: 12px 0;
  border-bottom: 1px solid #eee;
  display: flex;
  align-items: center;
  justify-content: space-between;
  
  &:last-child {
    border-bottom: none;
  }
`;

const ItemInfo = styled.div`
  display: flex;
  align-items: center;
  gap: 10px;
`;

const ItemCheckbox = styled.input`
  width: 20px;
  height: 20px;
  accent-color: #4CAF50;
  cursor: pointer;
`;

const ItemName = styled.span`
  color: #333;
  font-size: 1.1rem;
  text-decoration: ${props => props.checked ? 'line-through' : 'none'};
  color: ${props => props.checked ? '#999' : '#333'};
`;

const ItemQuantity = styled.span`
  color: #666;
  font-size: 0.95rem;
  padding: 4px 10px;
  background-color: #f0f0f0;
  border-radius: 20px;
`;

const ItemActions = styled.div`
  display: flex;
  gap: 8px;
`;

const ActionButton = styled.button`
  background-color: transparent;
  border: none;
  font-size: 1.2rem;
  cursor: pointer;
  padding: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #666;
  transition: all 0.2s ease;
  
  &:hover {
    color: ${props => props.delete ? '#f44336' : '#4CAF50'};
  }
`;

const RecipesPreview = styled.div`
  background-color: white;
  border-radius: 12px;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  padding: 30px;
  height: fit-content;
  position: sticky;
  top: 20px;
`;

const RecipesList = styled.div`
  margin-top: 20px;
`;

const RecipeItem = styled.div`
  border-bottom: 1px solid #eee;
  padding: 15px 0;
  
  &:last-child {
    border-bottom: none;
  }
`;

const RecipeTitle = styled.h3`
  margin: 0 0 10px 0;
  font-size: 1.2rem;
  color: #333;
`;

const RecipeIngredients = styled.ul`
  list-style-type: none;
  padding: 0;
  margin: 0;
`;

const RecipeIngredient = styled.li`
  padding: 8px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  
  button {
    opacity: 0;
    transition: opacity 0.2s ease;
  }
  
  &:hover button {
    opacity: 1;
  }
`;

const AddButton = styled.button`
  background-color: transparent;
  border: none;
  color: #4CAF50;
  cursor: pointer;
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  padding: 0;
  
  &:hover {
    text-decoration: underline;
  }
`;

const EmptyMessage = styled.div`
  text-align: center;
  padding: 40px 0;
  color: #666;
  
  p {
    margin-top: 15px;
    margin-bottom: 25px;
  }
`;

const FindRecipesButton = styled(Link)`
  display: inline-block;
  background-color: #4CAF50;
  color: white;
  text-decoration: none;
  padding: 12px 25px;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #45a049;
    transform: translateY(-2px);
  }
`;

const NoRecipeMessage = styled.div`
  color: #666;
  text-align: center;
  padding: 20px 0;
`;

// Örnek kategoriler
const categories = [
  { id: 'dairy', name: 'Süt Ürünleri' },
  { id: 'fruits', name: 'Meyve ve Sebzeler' },
  { id: 'meat', name: 'Et Ürünleri' },
  { id: 'bakery', name: 'Fırın Ürünleri' },
  { id: 'spices', name: 'Baharatlar' },
  { id: 'other', name: 'Diğer' }
];

// Örnek birimler
const units = [
  { id: 'piece', name: 'Adet' },
  { id: 'kg', name: 'Kilogram' },
  { id: 'g', name: 'Gram' },
  { id: 'l', name: 'Litre' },
  { id: 'ml', name: 'Mililitre' },
  { id: 'spoon', name: 'Yemek Kaşığı' },
  { id: 'teaspoon', name: 'Çay Kaşığı' },
  { id: 'cup', name: 'Su Bardağı' },
  { id: 'packet', name: 'Paket' },
  { id: 'none', name: 'Belirtilmemiş' }
];

// Örnek tarifler ve malzemeleri
const recipeExamples = [
  {
    id: 1,
    title: 'Ev Yapımı Lazanya',
    ingredients: [
      { id: 1, name: 'Kıyma', quantity: '500', unit: 'g', category: 'meat' },
      { id: 2, name: 'Lazanya yaprağı', quantity: '1', unit: 'packet', category: 'bakery' },
      { id: 3, name: 'Soğan', quantity: '2', unit: 'piece', category: 'fruits' },
      { id: 4, name: 'Sarımsak', quantity: '2', unit: 'piece', category: 'fruits' },
      { id: 5, name: 'Domates', quantity: '2', unit: 'piece', category: 'fruits' },
      { id: 6, name: 'Domates salçası', quantity: '2', unit: 'spoon', category: 'other' },
      { id: 7, name: 'Kaşar peyniri', quantity: '400', unit: 'g', category: 'dairy' },
      { id: 8, name: 'Lor peyniri', quantity: '200', unit: 'g', category: 'dairy' }
    ]
  },
  {
    id: 2,
    title: 'Mercimek Çorbası',
    ingredients: [
      { id: 9, name: 'Kırmızı mercimek', quantity: '1', unit: 'cup', category: 'other' },
      { id: 10, name: 'Havuç', quantity: '1', unit: 'piece', category: 'fruits' },
      { id: 11, name: 'Soğan', quantity: '1', unit: 'piece', category: 'fruits' },
      { id: 12, name: 'Sarımsak', quantity: '1', unit: 'piece', category: 'fruits' },
      { id: 13, name: 'Sıvı yağ', quantity: '2', unit: 'spoon', category: 'other' },
      { id: 14, name: 'Tuz', quantity: '1', unit: 'teaspoon', category: 'spices' },
      { id: 15, name: 'Karabiber', quantity: '1/2', unit: 'teaspoon', category: 'spices' }
    ]
  }
];

const ShoppingListPage = () => {
  const [items, setItems] = useState([]);
  const [itemName, setItemName] = useState('');
  const [itemQuantity, setItemQuantity] = useState('');
  const [itemUnit, setItemUnit] = useState('piece');
  const [itemCategory, setItemCategory] = useState('other');
  const [recipes, setRecipes] = useState(recipeExamples);
  
  // LocalStorage'dan alışveriş listesini çek
  useEffect(() => {
    const savedItems = localStorage.getItem('shoppingList');
    if (savedItems) {
      setItems(JSON.parse(savedItems));
    }
  }, []);
  
  // Alışveriş listesi değiştiğinde localStorage'a kaydet
  useEffect(() => {
    localStorage.setItem('shoppingList', JSON.stringify(items));
  }, [items]);
  
  // Yeni malzeme ekle
  const addItem = () => {
    if (!itemName.trim()) return;
    
    const newItem = {
      id: Date.now(),
      name: itemName,
      quantity: itemQuantity || '1',
      unit: itemUnit,
      category: itemCategory,
      checked: false
    };
    
    setItems([...items, newItem]);
    setItemName('');
    setItemQuantity('');
  };
  
  // Malzemeyi tariften alışveriş listesine ekle
  const addFromRecipe = (ingredient) => {
    // Aynı malzeme listede var mı kontrol et
    const existingItem = items.find(item => 
      item.name.toLowerCase() === ingredient.name.toLowerCase() && 
      item.unit === ingredient.unit
    );
    
    if (existingItem) {
      // Var olan malzemenin miktarını güncelle
      const updatedItems = items.map(item => {
        if (item.id === existingItem.id) {
          const newQuantity = parseFloat(item.quantity) + parseFloat(ingredient.quantity);
          return { ...item, quantity: newQuantity.toString() };
        }
        return item;
      });
      setItems(updatedItems);
    } else {
      // Yeni malzeme ekle
      const newItem = {
        id: Date.now(),
        name: ingredient.name,
        quantity: ingredient.quantity,
        unit: ingredient.unit,
        category: ingredient.category,
        checked: false
      };
      setItems([...items, newItem]);
    }
  };
  
  // Malzemeyi işaretle/işareti kaldır
  const toggleItem = (id) => {
    const updatedItems = items.map(item => 
      item.id === id ? { ...item, checked: !item.checked } : item
    );
    setItems(updatedItems);
  };
  
  // Malzemeyi düzenle
  const editItem = (id, updatedItem) => {
    const updatedItems = items.map(item => 
      item.id === id ? { ...item, ...updatedItem } : item
    );
    setItems(updatedItems);
  };
  
  // Malzemeyi sil
  const deleteItem = (id) => {
    const updatedItems = items.filter(item => item.id !== id);
    setItems(updatedItems);
  };
  
  // Listeyi temizle
  const clearList = () => {
    if (window.confirm('Alışveriş listesini temizlemek istediğinizden emin misiniz?')) {
      setItems([]);
    }
  };
  
  // Satın alınanları temizle
  const clearChecked = () => {
    const updatedItems = items.filter(item => !item.checked);
    setItems(updatedItems);
  };
  
  // Listeyi yazdır
  const printList = () => {
    window.print();
  };
  
  // Kategoriye göre malzemeleri grupla
  const groupedItems = items.reduce((acc, item) => {
    const category = item.category;
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(item);
    return acc;
  }, {});
  
  // Birim formatını düzeltme
  const formatUnit = (unit, quantity) => {
    const selectedUnit = units.find(u => u.id === unit);
    return selectedUnit ? selectedUnit.name : '';
  };
  
  return (
    <PageContainer>
      <PageHeader>
        <PageTitle>Alışveriş Listesi</PageTitle>
        <PageDescription>
          Tarifleriniz için gerekli malzemeleri buraya ekleyin, kategorilere göre düzenleyin ve alışverişe hazırlıklı çıkın.
        </PageDescription>
      </PageHeader>
      
      <ShoppingListContainer>
        <ShoppingListPanel>
          <PanelTitle>Alışveriş Listesi</PanelTitle>
          
          <InputGroup>
            <Input 
              type="text"
              placeholder="Malzeme adı girin"
              value={itemName}
              onChange={(e) => setItemName(e.target.value)}
            />
            <QuantityInput 
              type="text"
              placeholder="Miktar"
              value={itemQuantity}
              onChange={(e) => setItemQuantity(e.target.value)}
            />
            <Select 
              value={itemUnit}
              onChange={(e) => setItemUnit(e.target.value)}
            >
              {units.map(unit => (
                <option key={unit.id} value={unit.id}>{unit.name}</option>
              ))}
            </Select>
            <Button onClick={addItem} disabled={!itemName.trim()}>Ekle</Button>
          </InputGroup>
          
          <InputGroup>
            <Select 
              value={itemCategory}
              onChange={(e) => setItemCategory(e.target.value)}
            >
              {categories.map(category => (
                <option key={category.id} value={category.id}>{category.name}</option>
              ))}
            </Select>
          </InputGroup>
          
          {items.length > 0 ? (
            <ListContainer>
              {Object.keys(groupedItems).map(categoryId => {
                const categoryItems = groupedItems[categoryId];
                const category = categories.find(cat => cat.id === categoryId) || { name: 'Diğer' };
                
                return (
                  <CategoryList key={categoryId}>
                    <CategoryHeader>{category.name}</CategoryHeader>
                    <ItemList>
                      {categoryItems.map(item => (
                        <ItemRow key={item.id}>
                          <ItemInfo>
                            <ItemCheckbox 
                              type="checkbox"
                              checked={item.checked}
                              onChange={() => toggleItem(item.id)}
                            />
                            <ItemName checked={item.checked}>{item.name}</ItemName>
                            <ItemQuantity>
                              {item.quantity} {formatUnit(item.unit, item.quantity)}
                            </ItemQuantity>
                          </ItemInfo>
                          <ItemActions>
                            <ActionButton 
                              title="Sil"
                              delete
                              onClick={() => deleteItem(item.id)}
                            >
                              🗑️
                            </ActionButton>
                          </ItemActions>
                        </ItemRow>
                      ))}
                    </ItemList>
                  </CategoryList>
                );
              })}
              
              <ButtonsContainer>
                <ClearButton onClick={clearList}>Listeyi Temizle</ClearButton>
                <ClearButton onClick={clearChecked}>Satın Alınanları Sil</ClearButton>
                <PrintButton onClick={printList}>Listeyi Yazdır</PrintButton>
              </ButtonsContainer>
            </ListContainer>
          ) : (
            <EmptyMessage>
              <h3>Alışveriş Listeniz Boş</h3>
              <p>Yukarıdan malzeme ekleyebilir veya tariflerdeki malzemeleri listeye ekleyebilirsiniz.</p>
              <FindRecipesButton to="/recipes">Tariflere Göz At</FindRecipesButton>
            </EmptyMessage>
          )}
        </ShoppingListPanel>
        
        <SidePanel>
          <RecipesPreview>
            <PanelTitle>Tariflerim</PanelTitle>
            
            {recipes.length > 0 ? (
              <RecipesList>
                {recipes.map(recipe => (
                  <RecipeItem key={recipe.id}>
                    <RecipeTitle>{recipe.title}</RecipeTitle>
                    <RecipeIngredients>
                      {recipe.ingredients.map(ingredient => (
                        <RecipeIngredient key={ingredient.id}>
                          <span>{ingredient.name} ({ingredient.quantity} {formatUnit(ingredient.unit, ingredient.quantity)})</span>
                          <AddButton onClick={() => addFromRecipe(ingredient)}>+</AddButton>
                        </RecipeIngredient>
                      ))}
                    </RecipeIngredients>
                  </RecipeItem>
                ))}
              </RecipesList>
            ) : (
              <NoRecipeMessage>
                Henüz kaydedilmiş tarif bulunmuyor. Tarifleri keşfedin ve listeler oluşturun.
              </NoRecipeMessage>
            )}
          </RecipesPreview>
        </SidePanel>
      </ShoppingListContainer>
